// Generated by tools/make_icons.py (the same pixels as the PNGs in
// assets/voicechat/textures/gui/icons/): edit the grids there, not here.
//
// The icons pixel by pixel, for drawing them with fills where the game has no
// sprite for them (no content mod textures).
use crate::skin::Icon;
use crate::ui::Draw;

fn colour(c: u8) -> u32 {
    match c {
        b'K' => 0xFF202020,
        b'W' => 0xFFF0F0F0,
        b'G' => 0xFFB0B0B0,
        b'D' => 0xFF7A7A7A,
        b'R' => 0xFFE04040,
        b'B' => 0xFF60D0FF,
        b'Y' => 0xFFE8B830,
        b'L' => 0xFF50C850,
        _ => 0,
    }
}

